+/** Theoretical vs actual (consume) use per item between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    const day = s.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === s.dishId);
+    if (!dish) continue;
+    const recipe = store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) {
+      theoretical.set(n.itemId, round3((theoretical.get(n.itemId) ?? 0) + n.qty));
+    }
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, round3((actual.get(batch.itemId) ?? 0) + m.qty));
+  }
+  const rows = [];
+  for (const item of listItems(store)) {
+    const t = round3(theoretical.get(item.id) ?? 0);
+    const a = round3(actual.get(item.id) ?? 0);
+    if (t > 0 || a > 0) {
+      rows.push({ itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, diff: round3(a - t) });
+    }
+  }
+  return rows;
+}
